#!/bin/sh
terminal_profile_apply(){ p=$1; case $p in compatible) body='export TERM=${TERM:-xterm-256color}\nexport COLORTERM=${COLORTERM:-truecolor}\nexport LC_ALL=${LC_ALL:-C.UTF-8}';; minimal) body='export TERM=${TERM:-xterm}\nunset COLORTERM';; truecolor) body='export TERM=xterm-256color\nexport COLORTERM=truecolor';; esac; replace_block "$CURRENT_HOME/.profile" terminal "$body"; }
terminal_test(){ { printf 'TERM=%s\nCOLORTERM=%s\nLANG=%s\n' "${TERM:-}" "${COLORTERM:-}" "${LANG:-}"; printf 'Colors: '; i=0; while [ $i -lt 16 ]; do printf '\033[48;5;%sm  %s \033[0m' "$i" "$i"; i=$((i+1)); done; printf '\nUTF-8: ✓ λ 漢字\n'; } >"$TMP_DIR/termtest"; ui_text 'Terminal capability test' "$(cat "$TMP_DIR/termtest")"; }
terminal_tools_menu(){ while :; do c=$(ui_menu 'Terminal configuration' 'Terminal environment and multiplexer configuration.' wizards 'Selectable terminal configuration wizards' test 'Capability and Unicode test' profile 'Apply terminal compatibility profile' term 'Set TERM value' title 'Configure shell terminal title' tmux 'Configure tmux' screen 'Configure GNU screen' zellij 'Configure zellij' env 'Edit terminal environment block' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in wizards) terminal_wizards_menu;; test) terminal_test;; profile) p=$(ui_menu Profile 'Select profile.' compatible 'iSH-AOK compatible' truecolor '256 color / truecolor' minimal 'Minimal terminal') || continue; terminal_profile_apply "$p";; term) v=$(ui_input TERM 'TERM value' "${TERM:-xterm-256color}") || continue; replace_block "$CURRENT_HOME/.profile" term "export TERM='$v'";; title) replace_block "$CURRENT_HOME/.bashrc" terminal-title "case \$TERM in xterm*|screen*|tmux*) printf '\\033]0;%s@%s:%s\\007' \"\$USER\" \"\$(hostname)\" \"\$PWD\";; esac";; tmux) config_entry_menu tmux "$CURRENT_HOME/.tmux.conf" tmux;; screen) screen_wizard;; zellij) ensure_tool zellij zellij && config_entry_menu zellij "$CURRENT_HOME/.config/zellij/config.kdl" '';; env) edit_file "$CURRENT_HOME/.profile";; back) return;; esac; done; }
